function applyPreferences(){const p=S.preferences,root=document.documentElement;root.dataset.theme=p.theme;root.dataset.accent=p.accent;if(p.accent==='custom'&&/^#[0-9a-f]{6}$/i.test(p.customAccent)){root.style.setProperty('--accent',p.customAccent);root.style.setProperty('--accent-strong',`color-mix(in srgb, ${p.customAccent} 76%, #160923)`);root.style.setProperty('--accent-soft',`color-mix(in srgb, ${p.customAccent} 13%, var(--dash-card, #fff))`)}else{root.style.removeProperty('--accent');root.style.removeProperty('--accent-strong');root.style.removeProperty('--accent-soft')}root.classList.toggle('is-compact',p.compact);root.classList.toggle('reduce-motion',p.reducedMotion);root.classList.toggle('high-contrast',p.highContrast)}
function savePreference(key,value){const keys={reducedMotion:'cfs_motion',highContrast:'cfs_contrast',customAccent:'cfs_custom_accent'};S.preferences[key]=value;localStorage.setItem(keys[key]||`cfs_${key}`,String(value));applyPreferences()}
