const uiIcon=(name,className='')=>`<svg class="ui-icon ${className}" viewBox="0 0 24 24" aria-hidden="true">${UI_ICONS[name]||UI_ICONS.feedback}</svg>`;
function hydrateIcons(){$$('[data-icon]').forEach(node=>node.innerHTML=uiIcon(node.dataset.icon))}
function toast(message){const n=$('#toast');n.textContent=message;n.classList.add('is-visible');clearTimeout(toast.t);toast.t=setTimeout(()=>n.classList.remove('is-visible'),3000)}
function showError(error){console.error(error);const code=error.message||String(error),messages={ru:{passkey_unavailable:'Для этого аккаунта Face ID ещё не подключён.',challenge_expired:'Время подтверждения истекло. Попробуйте ещё раз.',invalid_passkey:'Не удалось подтвердить биометрию.',passkeys_not_supported:'Этот браузер не поддерживает биометрический вход.'},kk:{passkey_unavailable:'Бұл аккаунт үшін биометриялық кіру әлі қосылмаған.',challenge_expired:'Растау уақыты аяқталды. Қайта көріңіз.',invalid_passkey:'Биометрияны растау мүмкін болмады.',passkeys_not_supported:'Бұл браузер биометриялық кіруді қолдамайды.'},de:{passkey_unavailable:'Für dieses Konto ist noch kein Passkey eingerichtet.',challenge_expired:'Die Bestätigung ist abgelaufen. Bitte erneut versuchen.',invalid_passkey:'Biometrie konnte nicht bestätigt werden.',passkeys_not_supported:'Dieser Browser unterstützt keine biometrische Anmeldung.'},en:{passkey_unavailable:'Face ID or a passkey is not connected to this account yet.',challenge_expired:'Verification expired. Please try again.',invalid_passkey:'Biometric verification failed.',passkeys_not_supported:'This browser does not support biometric sign-in.'}};toast(messages[S.lang]?.[code]||code)}
async function api(path,{method='GET',data}={}){const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const out=await response.json().catch(()=>({error:'invalid_response'}));if(!response.ok){const e=new Error(out.error||'request_failed');e.status=response.status;throw e}return out}
function languageButtons(){return ['kk','ru','en','de'].map(l=>`<button class="lang ${S.lang===l?'is-current':''}" data-lang="${l}" type="button">${l==='kk'?'KZ':l.toUpperCase()}</button>`).join('')}
function applyLanguage(){document.documentElement.lang=S.lang;$$('[data-t]').forEach(n=>n.textContent=tr(n.dataset.t));$$('[data-lt]').forEach(n=>n.textContent=lt(n.dataset.lt));$$('[data-languages]').forEach(n=>n.innerHTML=languageButtons());renderNav()}
function setScreen(name){$('#loginView').classList.toggle('is-active',name==='login');$('#dashboardView').classList.toggle('is-active',name==='dashboard')}
function openAuthDialog(){const dialog=$('#authDialog');document.body.classList.add('auth-open');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;requestAnimationFrame(()=>dialog.querySelector('input')?.focus({preventScroll:true}))}
function closeAuthDialog(){const dialog=$('#authDialog');document.body.classList.remove('auth-open');if(dialog.open)dialog.close()}

async function init(){
  applyPreferences();hydrateIcons();applyLanguage();
  try{S.session=await api('/session');S.lang=S.session.user?.language||localStorage.getItem('cfs_lang')||'ru';applyLanguage();await routeSession()}catch(e){$('#authContent').innerHTML=`<div class="app-error">${esc(e.message)}<br><button class="button secondary error-retry" data-action="retry">Retry</button></div>`}
}
async function routeSession(){
  const s=S.session;setScreen('login');
  if(!s.authenticated){renderEmailAuth();return}
  if(!s.user){renderRegistration();return}
  if(!s.unlocked){renderUnlock();openAuthDialog();return}
  enterApp();
}
async function refreshSession(){S.session=await api('/session');return routeSession()}
function rolePicker(){const student=S.lang==='kk'?'Студент':S.lang==='ru'?'Студент':S.lang==='de'?'Student':'Student',teacher=S.lang==='kk'?'Оқытушы':S.lang==='ru'?'Преподаватель':S.lang==='de'?'Lehrkraft':'Teacher',label=S.lang==='kk'?'Аккаунт түрі':S.lang==='ru'?'Тип аккаунта':S.lang==='de'?'Kontotyp':'Account type';return `<fieldset class="role-picker"><legend>${label}</legend><div><label><input type="radio" name="role" value="student" checked><span>${uiIcon('courses')}<b>${student}</b></span></label><label><input type="radio" name="role" value="teacher"><span>${uiIcon('messages')}<b>${teacher}</b></span></label></div></fieldset>`}
function renderEmailAuth(mode='login'){
  const register=mode==='register';
  $('#authContent').innerHTML=register?`<form id="accountForm" class="input-stack">${rolePicker()}<label>${ac('name')}<input name="name" autocomplete="name" maxlength="80" required></label><label>${ac('email')}<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>${ac('password')}<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required><small>${ac('passwordHint')}</small></label><label>${ac('program')}<input name="program" autocomplete="organization-title" maxlength="120" placeholder="Computer Science · 3Y"></label><button class="primary-action" type="submit"><span>${ac('create')}</span><span>↗</span></button><button class="auth-alternate auth-link-button" data-auth-mode="login" type="button">${ac('existing')}</button></form>`:`<form id="loginForm" class="input-stack"><label>${ac('email')}<input name="email" type="email" autocomplete="username webauthn" maxlength="254" required></label><button class="biometric-button login-passkey" data-action="passkey-login" type="button">${uiIcon('fingerprint')}<span>${S.lang==='kk'?'FACE ID / БИОМЕТРИЯМЕН КІРУ':S.lang==='ru'?'ВОЙТИ ПО FACE ID / БИОМЕТРИИ':S.lang==='de'?'MIT FACE ID / BIOMETRIE ANMELDEN':'SIGN IN WITH FACE ID / BIOMETRICS'}</span></button><div class="auth-option-divider"><span>${S.lang==='kk'?'немесе құпиясөзбен':S.lang==='ru'?'или войти по паролю':S.lang==='de'?'oder mit Passwort':'or use password'}</span></div><label>${ac('password')}<input name="password" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><button class="primary-action" type="submit"><span>${ac('signIn')}</span><span>↗</span></button><button class="auth-alternate auth-link-button" data-auth-mode="register" type="button">${ac('newAccount')}</button></form>`;
}
function renderRegistration(){const s=S.session;$('#authContent').innerHTML=`<form id="registrationForm" class="input-stack">${rolePicker()}<p class="auth-identity"><strong>${esc(s.identity.name)}</strong>${esc(s.identity.email)}</p><label>${S.lang==='ru'?'Имя':'Name'}<input name="name" maxlength="80" required value="${esc(s.identity.name)}"></label><label>${S.lang==='ru'?'Программа / группа':'Program / group'}<input name="program" maxlength="120" placeholder="Computer Science · 3Y"></label><button class="primary-action" type="submit"><span>${S.lang==='ru'?'СОЗДАТЬ ПРОФИЛЬ':'CREATE PROFILE'}</span><span>↗</span></button></form>`}
function renderUnlock(){const s=S.session,password=s.authMethod==='password';$('#authContent').innerHTML=`<p class="auth-identity"><strong>${esc(s.user.name)}</strong>${esc(s.user.email)}</p>${s.hasPasskey?`<button class="biometric-button" data-action="passkey-auth">${uiIcon('fingerprint')}<span>${S.lang==='kk'?'БИОМЕТРИЯМЕН КІРУ':S.lang==='ru'?'ВОЙТИ ПО БИОМЕТРИИ':'USE DEVICE BIOMETRICS'}</span></button>`:''}${password?`<form id="unlockForm" class="input-stack compact-auth-form"><label>${ac('password')}<input name="password" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><button class="primary-action" type="submit"><span>${ac('unlock')}</span><span>↗</span></button></form>`:`<button class="primary-action" data-action="platform-unlock"><span>${S.lang==='kk'?'ЖАЛҒАСТЫРУ':S.lang==='ru'?'ПРОДОЛЖИТЬ':'CONTINUE'}</span><span>↗</span></button>`}<button class="auth-alternate auth-link-button" data-action="signout" type="button">${tr('signout')}</button>`}
function enterApp(){closeAuthDialog();setScreen('dashboard');updateProfile();renderNav();showPage(S.page)}
function updateProfile(){const u=S.session.user;$('#profileName').textContent=u.name;$('#profileProgram').textContent=u.program||u.role;$('#avatar').textContent=u.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'YU'}
function navItems(){const base=[['dashboard','house','dashboard'],['courses','courses','courses'],['feedback','feedback','feedback'],['notifications','bell','notifications']];if(['teacher','admin'].includes(S.session?.user?.role))base.push(['teacher','messages','teacher']);if(S.session?.user?.role==='admin')base.push(['admin','admin','admin']);return base}
function renderNav(){const nav=$('#mainNav');if(!nav)return;nav.innerHTML=navItems().map(([p,i,k],n)=>`<button class="nav-item ${S.page===p?'is-active':''}" data-page="${p}"><span class="nav-icon">${uiIcon(i)}</span><span>${tr(k)}</span><small>0${n+1}</small></button>`).join('')}
async function showPage(page){S.page=page;renderNav();$('#breadcrumbTitle').textContent=tr(page==='teacher'?'teacher':page==='admin'?'admin':page);const content=$('#content');content.classList.remove('page-enter');content.innerHTML=`<p class="muted">${tr('loading')}</p>`;closeMenu();try{if(page==='dashboard')await renderDashboard();else if(page==='courses')await renderCourses();else if(page==='feedback')await renderFeedback();else if(page==='notifications')await renderNotifications();else if(page==='settings')await renderSettings();else if(page==='teacher')await renderTeacher();else if(page==='admin')await renderAdmin();requestAnimationFrame(()=>content.classList.add('page-enter'))}catch(e){if(e.status===423){S.session.unlocked=false;return routeSession()}content.innerHTML=`<div class="app-error">${esc(e.message)}<div><button class="button secondary error-retry" data-page="${esc(page)}">Retry</button></div></div>`}}
async function loadCore(){const [c,f,n]=await Promise.all([api('/courses'),api('/feedback'),api('/notifications')]);S.cache={...S.cache,courses:c.courses,feedback:f.feedback,notifications:n.notifications};const unread=n.notifications.filter(x=>!x.is_read).length,badge=$('#notificationCount');badge.textContent=unread;badge.hidden=unread===0;return S.cache}
function pageHead(title,copy='',action=''){return `<section class="welcome-row"><div><p class="step-label">YESSENOV · COURSE FEEDBACK</p><h2>${esc(title)}</h2>${copy?`<p>${esc(copy)}</p>`:''}</div>${action}</section>`}
async function renderDashboard(){const d=await loadCore(),isStaff=['teacher','admin'].includes(S.session.user.role),staffFeedback=isStaff?(await api('/teacher/feedback')).feedback:[],courses=isStaff?d.courses.filter(c=>c.teacher_id===S.session.user.id):d.courses.filter(c=>c.enrollment_id),records=isStaff?staffFeedback:d.feedback,recordCount=records.length,avg=recordCount?records.reduce((a,x)=>a+(x.clarity+x.materials+x.support)/3,0)/recordCount:0,assignedLabel=S.lang==='ru'?'Назначенные курсы':S.lang==='kk'?'Тағайындалған курстар':S.lang==='de'?'Zugewiesene Kurse':'Assigned courses',feedbackLabel=S.lang==='ru'?'Отзывы студентов':S.lang==='kk'?'Студент пікірлері':S.lang==='de'?'Feedback der Studierenden':'Student feedback',statusLabel=S.lang==='ru'?'Получено':S.lang==='kk'?'Алынды':S.lang==='de'?'Erhalten':'Received';$('#content').innerHTML=pageHead(`${tr('hello')}, ${S.session.user.name.split(' ')[0]}.`,tr('ready'),`<button class="outline-action" data-page="courses"><span>${tr('catalog')}</span><span>↗</span></button>`)+`<section class="stats-grid"><article class="stat-card stat-dark"><span class="stat-label">${isStaff?assignedLabel:tr('active')}</span><strong class="stat-value">${String(courses.length).padStart(2,'0')}</strong><p><span class="status-dot blue"></span>${isStaff?assignedLabel:tr('open')}</p></article><article class="stat-card"><span class="stat-label">${isStaff?feedbackLabel:tr('sent')}</span><strong class="stat-value">${String(recordCount).padStart(2,'0')}</strong><p><span class="status-dot green"></span>${recordCount?(isStaff?statusLabel:tr('submitted')):tr('noFeedback')}</p></article><article class="stat-card rating-card"><span class="stat-label">${tr('average')}</span><strong class="stat-value rating-value"><span class="rating-number">${avg?avg.toFixed(1):'—'}</span><span class="rating-scale">/ 5</span></strong><p class="stars" aria-label="${avg?`${avg.toFixed(1)} ${tr('average')}`:tr('noFeedback')}">${avg?'★★★★★':'☆☆☆☆☆'}</p></article></section><section class="courses-section"><div class="section-heading"><div><p class="step-label">CURRENT SEMESTER</p><h3>${isStaff?assignedLabel:tr('courses')}</h3></div><button class="text-button strong" data-page="${isStaff?'teacher':'courses'}">${isStaff?feedbackLabel:tr('all')} →</button></div>${courseRows(courses,isStaff)}</section><footer class="dashboard-footer"><span>YESSENOV UNIVERSITY · STUDENT EXPERIENCE</span><a href="mailto:support@example.edu">${S.lang==='kk'?'Қолдау':S.lang==='ru'?'Поддержка':'Support'}: support@example.edu</a><span>COURSE FEEDBACK SYSTEM</span></footer>`}
function courseRows(rows,isStaff=false){const teacherFeedback=S.lang==='ru'?'Отзывы студентов':S.lang==='kk'?'Студент пікірлері':S.lang==='de'?'Feedback der Studierenden':'Student feedback';if(!rows.length)return `<div class="empty"><h3>${tr('noCourses')}</h3><button class="button" data-page="courses">${tr('catalog')}</button></div>`;return `<div class="course-list">${rows.map(c=>{const state=c.feedback_id?c.feedback_status:(c.open?'pending':'closed');return `<article class="course-row"><div class="course-code">${esc(c.code.split(/[- ]/)[0])}<br><strong>${esc(c.code.match(/\d+/)?.[0]||'')}</strong></div><div class="course-info"><h4>${esc(c.title)}</h4><p>${esc(c.teacher||'—')} · ${esc(c.semester)}</p></div><div class="course-meta"><span class="status ${state}">${tr(state)}</span><small>${date(c.closes)}</small></div>${isStaff?`<button class="course-action quiet" data-page="teacher"><span>${teacherFeedback}</span><span>→</span></button>`:c.feedback_id?`<button class="course-action quiet" data-view-feedback="${esc(c.id)}"><span>${c.open&&state==='submitted'?tr('edit'):tr('view')}</span><span>→</span></button>`:c.open?`<button class="course-action" data-feedback-course="${esc(c.id)}"><span>${tr('rate')}</span><span>↗</span></button>`:`<span></span>`}</article>`}).join('')}</div>`}
async function renderCourses(){const {courses}=await api('/courses'),isStaff=['teacher','admin'].includes(S.session.user.role),teacherFeedback=S.lang==='ru'?'Отзывы студентов':S.lang==='kk'?'Студент пікірлері':S.lang==='de'?'Feedback der Studierenden':'Student feedback';S.cache.courses=courses;$('#content').innerHTML=pageHead(tr('catalog'),S.lang==='ru'?(isStaff?'Назначенные вам курсы и поступившие отзывы студентов.':'Запишитесь на курс и оставьте отзыв до даты закрытия.'):(isStaff?'Your assigned courses and student feedback.':'Enroll and share feedback before the closing date.'))+`<div class="catalog-grid">${courses.length?courses.map(c=>`<article class="catalog-card"><span class="course-label">${esc(c.code)} · ${esc(c.semester)}</span><h3>${esc(c.title)}</h3><p>${esc(c.description||'—')}</p><div class="card-bottom"><span>${esc(c.teacher||'—')}</span><span>${c.open?tr('open'):tr('closed')} · ${date(c.closes)}</span></div><div class="button-row">${isStaff?(c.teacher_id===S.session.user.id?`<button class="button secondary" data-page="teacher">${teacherFeedback}</button>`:''):!c.enrollment_id&&c.open?`<button class="button" data-enroll="${esc(c.id)}">${tr('enroll')}</button>`:''}${!isStaff&&c.enrollment_id&&!c.feedback_id&&c.open?`<button class="button" data-feedback-course="${esc(c.id)}">${tr('rate')}</button>`:''}${!isStaff&&c.feedback_id?`<button class="button secondary" data-view-feedback="${esc(c.id)}">${tr('view')}</button>`:''}</div></article>`).join(''):`<div class="empty">${tr('noCourses')}</div>`}</div>`}
async function renderFeedback(){const {feedback}=await api('/feedback');S.cache.feedback=feedback;$('#content').innerHTML=pageHead(tr('myFeedback'))+(feedback.length?feedback.map(feedbackCard).join(''):`<div class="empty"><h3>${tr('noFeedback')}</h3><button class="button" data-page="courses">${tr('catalog')}</button></div>`)}
function feedbackCard(f){const avg=((f.clarity+f.materials+f.support)/3).toFixed(1);return `<article class="review-card"><div class="review-top"><div><span class="course-label">${esc(f.code)}</span><h3>${esc(f.title)}</h3></div><span class="status ${esc(f.status)}">${tr(f.status)}</span></div><div class="rating-summary"><span>${tr('average')} <strong>${avg}</strong></span><span>${tr('clarity')} <strong>${f.clarity}</strong></span><span>${tr('materials')} <strong>${f.materials}</strong></span><span>${tr('support')} <strong>${f.support}</strong></span></div>${f.comment?`<p class="review-content">${esc(f.comment)}</p>`:''}${f.response?`<div class="response"><strong>${S.lang==='ru'?'Ответ преподавателя':'Teacher response'}</strong>${esc(f.response)}</div>`:''}<p class="review-meta">${f.anonymous?tr('anonymous'):S.session.user.name} · ${date(f.created)}</p>${f.editable?`<button class="button secondary" data-feedback-course="${esc(f.course_id)}">${tr('edit')}</button>`:''}</article>`}
async function renderNotifications(){const {notifications}=await api('/notifications');S.cache.notifications=notifications;const unread=notifications.filter(x=>!x.is_read).length,badge=$('#notificationCount');badge.textContent=unread;badge.hidden=unread===0;$('#content').innerHTML=pageHead(tr('notifications'),'',unread?`<button class="outline-action" data-action="read-all"><span>${tr('markRead')}</span><span>✓</span></button>`:'')+(notifications.length?notifications.map(n=>`<article class="notification-row ${n.is_read?'':'unread'}"><h3>${n.kind==='reviewed'?(S.lang==='kk'?'Оқытушы пікірге жауап берді':S.lang==='ru'?'Преподаватель ответил на отзыв':'Teacher responded to feedback'):esc(n.kind)}</h3><p>${esc(n.course)} · ${date(n.created)}</p></article>`).join(''):`<div class="empty"><h3>${tr('noNotifications')}</h3></div>`)}
async function renderSettings(){const {passkeys}=await api('/passkeys');const u=S.session.user,p=S.preferences;$('#content').innerHTML=pageHead(tr('settings'))+`<div class="settings-grid settings-layout"><section class="section-card settings-card profile-settings"><div class="settings-card-head"><span class="settings-card-icon">${uiIcon('settings')}</span><div><h3>${tr('profile')}</h3><p>${S.lang==='kk'?'Жеке деректер мен интерфейс тілін өзгертіңіз.':S.lang==='ru'?'Личные данные и язык интерфейса.':'Personal details and interface language.'}</p></div></div><form id="profileForm" class="input-stack"><label>${S.lang==='kk'?'Аты-жөні':S.lang==='ru'?'Имя':'Name'}<input name="name" required maxlength="80" value="${esc(u.name)}"></label><label>${S.lang==='kk'?'Бағдарлама / топ':S.lang==='ru'?'Программа / группа':'Program / group'}<input name="program" maxlength="120" value="${esc(u.program)}"></label><label>Language<select name="language"><option value="kk" ${u.language==='kk'?'selected':''}>Қазақша</option><option value="ru" ${u.language==='ru'?'selected':''}>Русский</option><option value="en" ${u.language==='en'?'selected':''}>English</option><option value="de" ${u.language==='de'?'selected':''}>Deutsch</option></select></label><button class="button" type="submit">${tr('save')}</button></form></section><section class="section-card settings-card appearance-settings"><div class="settings-card-head"><span class="settings-card-icon">${uiIcon('palette')}</span><div><h3>${pc('appearance')}</h3><p>${pc('appearanceCopy')}</p></div></div><div class="preference-group"><span class="preference-label">${pc('theme')}</span><div class="theme-grid">${[['light','sun'],['soft','sparkles'],['dark','moon'],['system','monitor']].map(([value,ico])=>`<button type="button" class="theme-choice ${p.theme===value?'is-selected':''}" data-theme-choice="${value}">${uiIcon(ico)}<span>${pc(value)}</span></button>`).join('')}</div></div><div class="preference-group"><span class="preference-label">${pc('accent')}</span><div class="accent-row">${[['violet','#702cff'],['blue','#246bfd'],['teal','#0f9f8f'],['coral','#df5b55']].map(([value,color])=>`<button type="button" class="accent-choice ${p.accent===value?'is-selected':''}" data-accent-choice="${value}" aria-label="${value}"><span style="--swatch:${color}"></span></button>`).join('')}<label class="custom-accent ${p.accent==='custom'?'is-selected':''}" title="${S.lang==='kk'?'Кез келген түсті таңдаңыз':S.lang==='ru'?'Выбрать любой цвет':'Choose any color'}"><span class="rainbow-swatch"></span><input type="color" data-custom-accent value="${esc(p.customAccent)}" aria-label="${S.lang==='kk'?'Кез келген түс':S.lang==='ru'?'Любой цвет':'Any color'}"></label></div><small class="accent-help">${S.lang==='kk'?'Радуга белгісін басып, кез келген түсті таңдаңыз.':S.lang==='ru'?'Нажмите на радугу и выберите любой цвет.':'Select the rainbow to choose any color.'}</small></div><div class="preference-group"><span class="preference-label">${pc('comfort')}</span><label class="toggle-row"><span><b>${pc('compact')}</b><small>${S.lang==='kk'?'Экранға көбірек ақпарат сыйғызады.':S.lang==='ru'?'Больше информации помещается на экране.':'Fit more information on screen.'}</small></span><input type="checkbox" data-preference="compact" ${p.compact?'checked':''}><i></i></label><label class="toggle-row"><span><b>${pc('motion')}</b><small>${S.lang==='kk'?'Интерфейс қозғалысын азайтады.':S.lang==='ru'?'Снижает движение элементов интерфейса.':'Reduce interface movement.'}</small></span><input type="checkbox" data-preference="reducedMotion" ${p.reducedMotion?'checked':''}><i></i></label><label class="toggle-row"><span><b>${pc('contrast')}</b><small>${S.lang==='kk'?'Мәтін мен жиектерді айқынырақ етеді.':S.lang==='ru'?'Делает текст и границы заметнее.':'Make text and borders easier to see.'}</small></span><input type="checkbox" data-preference="highContrast" ${p.highContrast?'checked':''}><i></i></label></div></section><section class="section-card settings-card security-settings"><div class="settings-card-head"><span class="settings-card-icon">${uiIcon('fingerprint')}</span><div><h3>${pc('deviceSecurity')}</h3><p>${pc('passkeyCopy')}</p></div></div><button class="biometric-button" data-action="passkey-register">${uiIcon('fingerprint')}<span>${tr('addKey')}</span></button><div class="key-list">${passkeys.length?passkeys.map(k=>`<div class="key-row"><div><strong>${esc(k.label)}</strong><small>${date(k.created)}</small></div><button class="button danger" data-remove-key="${esc(k.id)}">${tr('remove')}</button></div>`).join(''):`<p class="muted">${tr('noKeys')}</p>`}</div></section></div>`}
async function renderTeacher(){if(!['teacher','admin'].includes(S.session.user.role))throw new Error('forbidden');const {feedback}=await api('/teacher/feedback');S.cache.teacherFeedback=feedback;$('#content').innerHTML=pageHead(tr('teacher'),S.lang==='ru'?'Авторство скрыто для анонимных отзывов.':'Anonymous submissions hide student identity.')+(feedback.length?feedback.map(f=>`<article class="review-card"><div class="review-top"><div><span class="course-label">${esc(f.code)}</span><h3>${esc(f.title)}</h3></div><span class="status ${esc(f.status)}">${tr(f.status)}</span></div><div class="rating-summary"><span>${tr('clarity')} <strong>${f.clarity}</strong></span><span>${tr('materials')} <strong>${f.materials}</strong></span><span>${tr('support')} <strong>${f.support}</strong></span></div><p class="review-content">${esc(f.comment||'—')}</p><p class="review-meta">${esc(f.student||tr('anonymous'))} · ${date(f.created)}</p>${f.response?`<div class="response"><strong>${S.lang==='ru'?'Ответ':'Response'}</strong>${esc(f.response)}</div>`:`<button class="button" data-review="${esc(f.id)}">${tr('respond')}</button>`}</article>`).join(''):`<div class="empty"><h3>${tr('noFeedback')}</h3></div>`)}
async function renderAdmin(){if(S.session.user.role!=='admin')throw new Error('forbidden');const [users,courses]=await Promise.all([api('/admin/users'),api('/admin/courses')]);S.cache.admin={users:users.users,courses:courses.courses};$('#content').innerHTML=pageHead(tr('admin'))+`<section class="section-card"><div class="section-heading"><h3>${tr('manageCourses')}</h3><button class="button" data-action="course-create">${tr('createCourse')}</button></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>${S.lang==='ru'?'Название':'Title'}</th><th>${S.lang==='ru'?'Преподаватель':'Teacher'}</th><th>${S.lang==='ru'?'До':'Closes'}</th><th></th></tr></thead><tbody>${courses.courses.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.title)}</td><td>${esc(c.teacher||'—')}</td><td>${date(c.closes)}</td><td><button class="button secondary" data-edit-course="${esc(c.id)}">${tr('edit')}</button></td></tr>`).join('')}</tbody></table></div></section><section class="section-card"><h3>${tr('users')}</h3><div class="table-wrap"><table><thead><tr><th>${S.lang==='ru'?'Имя':'Name'}</th><th>Email</th><th>${S.lang==='ru'?'Программа':'Program'}</th><th>${S.lang==='ru'?'Роль':'Role'}</th></tr></thead><tbody>${users.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.program||'—')}</td><td><select data-role-user="${esc(u.id)}" ${u.id===S.session.user.id?'disabled':''}><option value="student" ${u.role==='student'?'selected':''}>student</option><option value="teacher" ${u.role==='teacher'?'selected':''}>teacher</option>${['support@example.edu','admin@example.edu'].includes(u.email.toLowerCase())?`<option value="admin" ${u.role==='admin'?'selected':''}>admin</option>`:''}</select></td></tr>`).join('')}</tbody></table></div></section>`}

function modal(title,html){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=html;$('#modal').showModal()}
function feedbackModal(courseId){const c=S.cache.courses?.find(x=>x.id===courseId),f=S.cache.feedback?.find(x=>x.course_id===courseId);if(!c)return toast('course_not_found');const rating=(name,label,value)=>`<fieldset class="rating-field"><legend>${label}</legend><div class="rating-options">${[1,2,3,4,5].map(n=>`<label class="rating-option"><input type="radio" name="${name}" value="${n}" ${value===n?'checked':''} required><span>${n}</span></label>`).join('')}</div></fieldset>`;modal(c.title,`<form id="feedbackForm" class="input-stack" data-course="${esc(courseId)}" data-method="${f?'PATCH':'POST'}">${rating('clarity',tr('clarity'),f?.clarity)}${rating('materials',tr('materials'),f?.materials)}${rating('support',tr('support'),f?.support)}<label>${tr('comment')}<textarea name="comment" maxlength="2000">${esc(f?.comment||'')}</textarea></label><label class="check-row"><input type="checkbox" name="anonymous" ${f?.anonymous!==0?'checked':''}><span>${tr('anonymousLabel')}</span></label><button class="button" type="submit">${f?tr('update'):tr('send')}</button></form>`)}
function reviewModal(id){modal(tr('respond'),`<form id="reviewForm" class="input-stack" data-id="${esc(id)}"><label>${tr('respond')}<textarea name="response" maxlength="2000" required></textarea></label><button class="button" type="submit">${tr('respond')}</button></form>`)}
function courseModal(id){const c=S.cache.admin.courses.find(x=>x.id===id),teachers=S.cache.admin.users.filter(x=>['teacher','admin'].includes(x.role));modal(c?tr('edit'):tr('createCourse'),`<form id="courseForm" class="form-grid" data-id="${esc(c?.id||'')}"><label>Code<input name="code" maxlength="20" required value="${esc(c?.code||'')}"></label><label>${S.lang==='ru'?'Название':'Title'}<input name="title" maxlength="160" required value="${esc(c?.title||'')}"></label><label class="wide">${S.lang==='ru'?'Описание':'Description'}<textarea name="description" maxlength="1000">${esc(c?.description||'')}</textarea></label><label>${S.lang==='ru'?'Преподаватель':'Teacher'}<select name="teacherId"><option value="">—</option>${teachers.map(u=>`<option value="${esc(u.id)}" ${c?.teacher_id===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>${S.lang==='ru'?'Семестр':'Semester'}<input name="semester" maxlength="60" required value="${esc(c?.semester||'Spring 2027')}"></label><label>${S.lang==='ru'?'Дата закрытия':'Closing date'}<input type="date" name="closes" required value="${esc(c?.closes||'2027-06-01')}"></label><label class="check-row"><input type="checkbox" name="active" ${c?.active!==0?'checked':''}><span>${tr('open')}</span></label><button class="button wide" type="submit">${tr('save')}</button></form>`)}
function closeMenu(){$('#sidebar').classList.remove('is-open');$('#sidebarScrim').classList.remove('is-visible');document.body.classList.remove('menu-open');$('#menuButton').setAttribute('aria-expanded','false');$('#menuButton').setAttribute('aria-label','Open menu');$('#menuButton').innerHTML=uiIcon('menu')}
function toggleMenu(){const open=!$('#sidebar').classList.contains('is-open');$('#sidebar').classList.toggle('is-open',open);$('#sidebarScrim').classList.toggle('is-visible',open);document.body.classList.toggle('menu-open',open);$('#menuButton').setAttribute('aria-expanded',String(open));$('#menuButton').setAttribute('aria-label',open?'Close menu':'Open menu');$('#menuButton').innerHTML=uiIcon(open?'close':'menu')}

function b64buf(value){const s=value.replace(/-/g,'+').replace(/_/g,'/');const b=atob(s+'==='.slice((s.length+3)%4));return Uint8Array.from(b,c=>c.charCodeAt(0)).buffer}
function buf64(value){const b=new Uint8Array(value);let s='';b.forEach(x=>s+=String.fromCharCode(x));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function credentialJSON(c){return {id:c.id,rawId:buf64(c.rawId),type:c.type,clientExtensionResults:c.getClientExtensionResults(),authenticatorAttachment:c.authenticatorAttachment,response:c.response.attestationObject?{attestationObject:buf64(c.response.attestationObject),clientDataJSON:buf64(c.response.clientDataJSON),transports:c.response.getTransports?.()||[]}:{authenticatorData:buf64(c.response.authenticatorData),clientDataJSON:buf64(c.response.clientDataJSON),signature:buf64(c.response.signature),userHandle:c.response.userHandle?buf64(c.response.userHandle):null}}}
function authenticationOptions(options){return {...options,challenge:b64buf(options.challenge),allowCredentials:options.allowCredentials?.map(key=>({...key,id:b64buf(key.id)}))}}
async function confirmPasskey(response,verifyPath){const credential=await navigator.credentials.get({publicKey:authenticationOptions(response.options)});await api(verifyPath,{method:'POST',data:{challengeId:response.challengeId,response:credentialJSON(credential)}});await refreshSession()}
async function passkeyAuth(){if(!window.PublicKeyCredential)throw new Error('passkeys_not_supported');await confirmPasskey(await api('/passkeys/authenticate/options',{method:'POST',data:{}}),'/passkeys/authenticate/verify')}
function passkeyOptions(email){const normalized=email.trim().toLowerCase(),time=Date.now();if(passkeyWarm.email===normalized&&time<passkeyWarm.expires){if(passkeyWarm.result)return Promise.resolve(passkeyWarm.result);if(passkeyWarm.error)return Promise.reject(passkeyWarm.error);if(passkeyWarm.promise)return passkeyWarm.promise}passkeyWarm.email=normalized;passkeyWarm.result=null;passkeyWarm.error=null;passkeyWarm.expires=0;const request=api('/auth/passkey/options',{method:'POST',data:{email:normalized}}).then(result=>{if(passkeyWarm.email===normalized){passkeyWarm.result=result;passkeyWarm.expires=Date.now()+240000}return result}).catch(error=>{if(passkeyWarm.email===normalized&&error.message==='passkey_unavailable'){passkeyWarm.error=error;passkeyWarm.expires=Date.now()+30000}throw error}).finally(()=>{if(passkeyWarm.email===normalized)passkeyWarm.promise=null});passkeyWarm.promise=request;return request}
function warmPasskey(email){const normalized=email.trim().toLowerCase();if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized))passkeyOptions(normalized).catch(()=>{})}
async function passkeyLogin(){if(!window.PublicKeyCredential||!navigator.credentials)throw new Error(S.lang==='ru'?'Биометрический вход не поддерживается этим браузером':'passkeys_not_supported');const email=$('#loginForm input[name="email"]'),button=$('[data-action="passkey-login"]');if(!email?.value.trim()){email?.focus();throw new Error(S.lang==='ru'?'Сначала введите Email':'Enter your email first')}button.disabled=true;try{await confirmPasskey(await passkeyOptions(email.value),'/auth/passkey/verify')}finally{button.disabled=false}}
function devicePasskeyName(){const ua=navigator.userAgent;if(/iPhone|iPad|Macintosh/.test(ua))return 'Apple Face ID / Touch ID';if(/Android/.test(ua))return 'Android biometric passkey';if(/Windows/.test(ua))return 'Windows Hello';return 'Device biometric passkey'}
async function passkeyRegister(){if(!window.PublicKeyCredential||!navigator.credentials)throw new Error(S.lang==='ru'?'Биометрический вход не поддерживается этим браузером':'passkeys_not_supported');const r=await api('/passkeys/register/options',{method:'POST',data:{}}),o=r.options;o.challenge=b64buf(o.challenge);o.user={...o.user,id:b64buf(o.user.id)};o.excludeCredentials=o.excludeCredentials?.map(x=>({...x,id:b64buf(x.id)}));const c=await navigator.credentials.create({publicKey:o});await api('/passkeys/register/verify',{method:'POST',data:{challengeId:r.challengeId,label:devicePasskeyName(),response:credentialJSON(c)}});toast(S.lang==='kk'?'Биометриялық кілт қосылды':S.lang==='ru'?'Биометрический ключ подключён':'Biometric passkey added');await renderSettings()}

document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{
  if(el.dataset.themeChoice){savePreference('theme',el.dataset.themeChoice);renderSettings();toast(pc('preferencesSaved'));return}
  if(el.dataset.accentChoice){savePreference('accent',el.dataset.accentChoice);renderSettings();toast(pc('preferencesSaved'));return}
  if(el.dataset.lang){S.lang=el.dataset.lang;localStorage.setItem('cfs_lang',S.lang);applyLanguage();if(S.session?.user&&S.session.unlocked)await api('/profile',{method:'PATCH',data:{name:S.session.user.name,program:S.session.user.program,language:S.lang}});if(S.session?.user&&S.session.unlocked)showPage(S.page);else if(S.session)routeSession();return}
  if(el.dataset.action==='auth-open'){openAuthDialog();return}
  if(el.dataset.action==='auth-close'){closeAuthDialog();return}
  if(el.dataset.action==='menu-close'){closeMenu();return}
  if(el.dataset.scroll){document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return}
  if(el.dataset.authMode){renderEmailAuth(el.dataset.authMode);return}
  if(el.dataset.page){showPage(el.dataset.page);return}
  if(el.dataset.action==='retry'){init();return}
  if(el.dataset.action==='platform-unlock'){await api('/unlock/platform',{method:'POST',data:{}});await refreshSession();return}
  if(el.dataset.action==='passkey-auth'){await passkeyAuth();return}
  if(el.dataset.action==='passkey-login'){await passkeyLogin();return}
  if(el.dataset.action==='passkey-register'){await passkeyRegister();return}
  if(el.dataset.action==='lock'){await api('/lock',{method:'POST',data:{}});await refreshSession();return}
  if(el.dataset.action==='signout'){if(S.session?.authMethod==='password'){await api('/auth/logout',{method:'POST',data:{}});S.session={authenticated:false};closeAuthDialog();routeSession()}else location.href='/signout-with-chatgpt?return_to=/';return}
  if(el.dataset.action==='read-all'){await api('/notifications/read',{method:'POST',data:{}});renderNotifications();return}
  if(el.dataset.action==='course-create'){courseModal();return}
  if(el.dataset.enroll){await api('/enroll',{method:'POST',data:{courseId:el.dataset.enroll}});toast(S.lang==='ru'?'Вы записаны на курс':'Enrolled');renderCourses();return}
  if(el.dataset.feedbackCourse){if(!S.cache.feedback)S.cache.feedback=(await api('/feedback')).feedback;feedbackModal(el.dataset.feedbackCourse);return}
  if(el.dataset.viewFeedback){showPage('feedback');return}
  if(el.dataset.review){reviewModal(el.dataset.review);return}
  if(el.dataset.editCourse){courseModal(el.dataset.editCourse);return}
  if(el.dataset.removeKey){await api('/passkeys',{method:'DELETE',data:{id:el.dataset.removeKey}});renderSettings();return}
}catch(err){if(err.name==='NotAllowedError')toast(S.lang==='ru'?'Подтверждение отменено':'Verification cancelled');else showError(err)}});
document.addEventListener('change',async e=>{if(e.target.dataset.customAccent!==undefined){savePreference('customAccent',e.target.value);savePreference('accent','custom');renderSettings();toast(pc('preferencesSaved'));return}if(e.target.dataset.preference){savePreference(e.target.dataset.preference,e.target.checked);toast(pc('preferencesSaved'));return}if(e.target.dataset.roleUser)try{await api('/admin/role',{method:'PATCH',data:{id:e.target.dataset.roleUser,role:e.target.value}});toast(tr('save'))}catch(err){showError(err);renderAdmin()}});
document.addEventListener('input',e=>{if(!e.target.matches('#loginForm input[name="email"]'))return;clearTimeout(passkeyWarmTimer);passkeyWarmTimer=setTimeout(()=>warmPasskey(e.target.value),450)});
document.addEventListener('focusout',e=>{if(e.target.matches('#loginForm input[name="email"]'))warmPasskey(e.target.value)});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f));try{
  if(f.id==='loginForm'){await api('/auth/login',{method:'POST',data:{email:b.email,password:b.password}});await refreshSession()}
  if(f.id==='accountForm'){await api('/auth/register',{method:'POST',data:{name:b.name,email:b.email,password:b.password,program:b.program,language:S.lang,role:b.role}});await refreshSession()}
  if(f.id==='unlockForm'){await api('/auth/unlock',{method:'POST',data:{password:b.password}});await refreshSession()}
  if(f.id==='registrationForm'){await api('/profile',{method:'POST',data:{name:b.name,program:b.program,language:S.lang,role:b.role}});await refreshSession()}
  if(f.id==='profileForm'){await api('/profile',{method:'PATCH',data:{name:b.name,program:b.program,language:b.language}});S.session=await api('/session');S.lang=b.language;applyLanguage();updateProfile();toast(tr('save'))}
  if(f.id==='feedbackForm'){await api('/feedback',{method:f.dataset.method,data:{courseId:f.dataset.course,clarity:Number(b.clarity),materials:Number(b.materials),support:Number(b.support),comment:b.comment||'',anonymous:b.anonymous==='on'}});$('#modal').close();toast(tr('submitted'));S.cache={};showPage('feedback')}
  if(f.id==='reviewForm'){await api('/teacher/review',{method:'POST',data:{id:f.dataset.id,response:b.response}});$('#modal').close();toast(tr('reviewed'));renderTeacher()}
  if(f.id==='courseForm'){await api('/admin/courses',{method:f.dataset.id?'PATCH':'POST',data:{id:f.dataset.id||undefined,code:b.code,title:b.title,description:b.description,teacherId:b.teacherId,semester:b.semester,closes:b.closes,active:b.active==='on'}});$('#modal').close();toast(tr('save'));renderAdmin()}
}catch(err){showError(err)}});
$('#menuButton').addEventListener('click',toggleMenu);$('#sidebarScrim').addEventListener('click',closeMenu);window.addEventListener('resize',()=>{if(innerWidth>960)closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('is-open'))closeMenu()});$('#closeModal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});$('#authDialog').addEventListener('click',e=>{if(e.target===$('#authDialog'))closeAuthDialog()});$('#authDialog').addEventListener('close',()=>document.body.classList.remove('auth-open'));
init();
